var STORAGE_KEY="sklad_products",AUTH_KEY="sklad_auth";function storeGet(t){try{var e=window.localStorage.getItem(t);if(null!==e)return e}catch(t){}try{var r=window.sessionStorage.getItem(t);if(null!==r)return r}catch(t){}try{var n=new RegExp("(?:^|;)"+t+"=([^;]*)").exec(window.name||"");if(n)return decodeURIComponent(n[1])}catch(t){}return null}function storeSet(t,e){try{window.localStorage.setItem(t,e)}catch(t){}try{window.sessionStorage.setItem(t,e)}catch(t){}try{var r=(window.name||"").replace(new RegExp("(?:^|;)"+t+"=[^;]*"),"").replace(/^;/,"");window.name=(r?r+";":"")+t+"="+encodeURIComponent(e)}catch(t){}}function storeRemove(t){try{window.localStorage.removeItem(t)}catch(t){}try{window.sessionStorage.removeItem(t)}catch(t){}try{window.name=(window.name||"").replace(new RegExp("(?:^|;)"+t+"=[^;]*"),"").replace(/^;/,"")}catch(t){}}var DEFAULT_PRODUCTS=[{id:"drill",name:"Аккумуляторная дрель",title:"Аккумуляторная дрель-шуруповерт DeWalt",art:"DEW-DCD701",qty:12,img:"assets/img/p_1_drill.png",photo:"assets/img/drill_big.png",desc:"Профессиональный инструмент DeWalt DCD701. Бесщеточный двигатель обеспечивает высокую производительность и долгий срок службы. Комплектуется ударопрочным кейсом, двумя литий-ионными аккумуляторами 2.0 Ач и быстрым зарядным устройством."},{id:"helmet",name:"Защитная каска",title:"Защитная каска строительная",art:"SAF-HELM-01",qty:45,img:"assets/img/p_2_helmet.png",photo:"assets/img/p_2_helmet.png",desc:"Каска из высокопрочного полиэтилена с внутренней амортизирующей системой. Выдерживает удары сверху и по бокам, регулируется по размеру головы ремешком. Предназначена для работ на строительной площадке и на производстве."},{id:"boxes",name:"Упаковочные коробки",title:"Упаковочные коробки гофрированные",art:"PKG-BOX-5S",qty:120,img:"assets/img/p_3_boxes.png",photo:"assets/img/p_3_boxes.png",desc:"Гофрокоробки пятислойные размером 400×300×300 мм. Выдерживают нагрузку до 30 кг, устойчивы к влаге и деформации при штабелировании. Поставляются в плоском виде, сборка без скотча по вертикальным углам."},{id:"projector",name:"Светодиодный прожектор",title:"Светодиодный прожектор 100 Вт",art:"LED-FLD-100",qty:8,img:"assets/img/p_4_projector.png",photo:"assets/img/p_4_projector.png",desc:"Уличный светодиодный прожектор мощностью 100 Вт с корпусом IP65. Световой поток 10000 лм, температура света 4000 К. Монтируется на кронштейн, рабочий температурный диапазон от −40 °C до +50 °C."},{id:"gloves",name:"Перчатки рабочие",title:"Перчатки рабочие с нитриловым покрытием",art:"PPE-GLV-L",qty:250,img:"assets/img/p_5_gloves.png",photo:"assets/img/p_5_gloves.png",desc:"Перчатки из трикотажной основы с нитриловым покрытием ладони. Обеспечивают надёжный захват мокрых и масляных деталей, сохраняют подвижность пальцев. Размер L, износостойкость класса 4."},{id:"paint",name:"Ведро фасадной краски",title:"Ведро фасадной краски 15 кг",art:"PAINT-FS-15",qty:15,img:"assets/img/p_6_paint.png",photo:"assets/img/p_6_paint.png",desc:"Фасадная краска на акриловой основе для наружных работ. Образует прочное матовое покрытие, устойчивое к осадкам и ультрафиолету. Расход 0,3 л/м² на два слоя, полное высыхание за 4 часа."}];function getProducts(){var t=storeGet(STORAGE_KEY);if(!t)return DEFAULT_PRODUCTS.slice();try{var e=JSON.parse(t);return Array.isArray(e)?e:DEFAULT_PRODUCTS.slice()}catch(t){return DEFAULT_PRODUCTS.slice()}}function saveProducts(t){storeSet(STORAGE_KEY,JSON.stringify(t))}function getProduct(t){for(var e=getProducts(),r=0;r<e.length;r++)if(e[r].id===t)return e[r];return null}function removeProduct(t){var e=getProducts().filter(function(e){return e.id!==t});return saveProducts(e),e}function upsertProduct(t){for(var e=getProducts(),r=!1,n=0;n<e.length;n++)e[n].id===t.id&&(e[n]=t,r=!0);return r||e.push(t),saveProducts(e),e}function isLoggedIn(){return"1"===storeGet(AUTH_KEY)}function logIn(){storeSet(AUTH_KEY,"1")}function logOut(){storeRemove(AUTH_KEY)}